import json
import re
from docx import Document
from docx.text.paragraph import Paragraph

TEMPLATE = '/root/offer_letter_template.docx'
DATA = '/root/employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA, 'r', encoding='utf-8') as f:
    data = json.load(f)

include_relocation = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

start_marker = '{{IF_RELOCATION}}'
end_marker = '{{END_IF_RELOCATION}}'

pattern_placeholder = re.compile(r'\{\{([A-Z0-9_]+)\}\}')

def set_paragraph_text(para: Paragraph, text: str) -> None:
    runs = para.runs
    if runs:
        runs[0].text = text
        for run in runs[1:]:
            run.text = ''
    else:
        para.add_run(text)


def delete_paragraph(para: Paragraph) -> None:
    p = para._element
    parent = p.getparent()
    if parent is not None:
        parent.remove(p)
    para._p = para._element = None


def process_conditional_paragraphs(paragraphs, include: bool) -> None:
    to_delete = []
    in_cond = False
    for para in list(paragraphs):
        text = para.text

        if not in_cond:
            if start_marker in text:
                if end_marker in text:
                    if include:
                        new_text = text.replace(start_marker, '').replace(end_marker, '')
                        set_paragraph_text(para, new_text)
                    else:
                        seg_pattern = re.escape(start_marker) + r'.*?' + re.escape(end_marker)
                        new_text = re.sub(seg_pattern, '', text)
                        if new_text.strip() == '':
                            to_delete.append(para)
                        else:
                            set_paragraph_text(para, new_text)
                    # not entering conditional block
                else:
                    if include:
                        new_text = text.replace(start_marker, '')
                        set_paragraph_text(para, new_text)
                    else:
                        to_delete.append(para)
                    in_cond = True
                continue
        else:
            if end_marker in text:
                if include:
                    new_text = text.replace(end_marker, '')
                    set_paragraph_text(para, new_text)
                else:
                    # Keep any text after end marker if present
                    after = text.split(end_marker, 1)[1]
                    if after.strip() == '':
                        to_delete.append(para)
                    else:
                        set_paragraph_text(para, after)
                in_cond = False
                continue
            else:
                if not include:
                    to_delete.append(para)
                continue

    for para in to_delete:
        delete_paragraph(para)


def replace_placeholders_in_paragraphs(paragraphs, data_dict) -> None:
    for para in list(paragraphs):
        text = para.text
        if not text:
            continue
        if not pattern_placeholder.search(text):
            continue
        new_text = text
        for match in pattern_placeholder.finditer(text):
            key = match.group(1)
            if key in data_dict:
                new_text = new_text.replace(match.group(0), str(data_dict[key]))
        if new_text != text:
            set_paragraph_text(para, new_text)


def process_table_conditionals(table, include: bool) -> None:
    for row in table.rows:
        for cell in row.cells:
            process_conditional_paragraphs(cell.paragraphs, include)
            for nested in cell.tables:
                process_table_conditionals(nested, include)


def process_table_replacements(table, data_dict) -> None:
    for row in table.rows:
        for cell in row.cells:
            replace_placeholders_in_paragraphs(cell.paragraphs, data_dict)
            for nested in cell.tables:
                process_table_replacements(nested, data_dict)


doc = Document(TEMPLATE)

# Conditionals in main body
process_conditional_paragraphs(doc.paragraphs, include_relocation)
for table in doc.tables:
    process_table_conditionals(table, include_relocation)

# Conditionals in headers/footers
for section in doc.sections:
    process_conditional_paragraphs(section.header.paragraphs, include_relocation)
    for table in section.header.tables:
        process_table_conditionals(table, include_relocation)
    process_conditional_paragraphs(section.footer.paragraphs, include_relocation)
    for table in section.footer.tables:
        process_table_conditionals(table, include_relocation)

# Replace placeholders in main body
replace_placeholders_in_paragraphs(doc.paragraphs, data)
for table in doc.tables:
    process_table_replacements(table, data)

# Replace placeholders in headers/footers
for section in doc.sections:
    replace_placeholders_in_paragraphs(section.header.paragraphs, data)
    for table in section.header.tables:
        process_table_replacements(table, data)
    replace_placeholders_in_paragraphs(section.footer.paragraphs, data)
    for table in section.footer.tables:
        process_table_replacements(table, data)

# Save
 doc = doc

doc.save(OUTPUT)
print('Saved', OUTPUT)
